#ifndef FONTS_H
#define FONTS_H

#include <stdint.h>

// Monospaced bitmap font, generated by tools/gen_font.py. The table holds one glyph per character
// from ' ' to Last; each glyph is Height rows of (Width + 7) / 8 bytes, MSB = leftmost pixel.
typedef struct
{
    const uint8_t *table;
    uint16_t Width;
    uint16_t Height;
    uint16_t Last; // last character in the table
} sFONT;

extern sFONT Font22; // 11x22, body text
extern sFONT Font28; // 14x28, titles

#endif
